import json
from collections import defaultdict

# Load input data
with open('/app/task_file/input_data/tests.json', 'r') as f:
    tests = json.load(f)

with open('/app/task_file/input_data/runners.json', 'r') as f:
    runners = json.load(f)

with open('/app/task_file/input_data/scheduling_constraints.json', 'r') as f:
    constraints = json.load(f)

# Build lookup structures
test_map = {t['test_id']: t for t in tests}
runner_map = {r['runner_id']: r for r in runners}

def compute_earliest_wave(test_id, computed=None):
    if computed is None:
        computed = {}
    if test_id in computed:
        return computed[test_id]
    deps = test_map[test_id]['dependencies']
    if not deps:
        computed[test_id] = 1
        return 1
    max_dep_wave = 0
    for dep in deps:
        dw = compute_earliest_wave(dep, computed)
        if dw > max_dep_wave:
            max_dep_wave = dw
    computed[test_id] = max_dep_wave + 1
    return computed[test_id]

# Compute earliest wave for each test
earliest_wave = {}
for t in tests:
    compute_earliest_wave(t['test_id'], earliest_wave)

# Build category -> runner list mapping
category_runners = defaultdict(list)
for r in runners:
    for cat in r['supported_categories']:
        category_runners[cat].append(r)

# Build runner -> categories mapping
runner_categories = {r['runner_id']: r['supported_categories'] for r in runners}

# Build runner capacity
runner_capacity = {}
for r in runners:
    runner_capacity[r['runner_id']] = {
        'cpu': r['cpu_cores'],
        'memory': r['memory_mb']
    }

# Build mutual exclusion groups: set of test pairs that cannot be in same wave
mutual_exclusion = set()
for group in constraints['mutual_exclusion_groups']:
    for i in range(len(group)):
        for j in range(i+1, len(group)):
            mutual_exclusion.add((group[i], group[j]))

# Build affinity requirements
affinity = constraints['affinity_requirements']

# Build critical tests and flaky tests
critical_reliability_threshold = constraints['critical_test_min_reliability']
flaky_threshold = constraints['flaky_test_isolation_threshold']
critical_tests = [t['test_id'] for t in tests if t.get('is_critical', False)]
flaky_tests = [t['test_id'] for t in tests if t['flaky_probability'] >= flaky_threshold]

# Build priority groups
priority = {
    'blocking': constraints['priority_groups']['blocking'],
    'high': constraints['priority_groups']['high'],
    'normal': constraints['priority_groups']['normal']
}

# Build test info
flaky = {}
critical = {}
for t in tests:
    flaky[t['test_id']] = t['flaky_probability'] >= flaky_threshold
    critical[t['test_id']] = t.get('is_critical', False)

category = {}
for t in tests:
    category[t['test_id']] = t['category']

cpu = {}
memory = {}
gpu_required = {}
for t in tests:
    cpu[t['test_id']] = t['cpu_cores']
    memory[t['test_id']] = t['memory_mb']
    gpu_required[t['test_id']] = t['gpu_required']

# Sort tests by earliest wave ascending, then by some tiebreaker
sorted_tests = sorted(tests, key=lambda t: (earliest_wave[t['test_id']], -t.get('coverage_impact', 0), t['test_id']))

# Track assignments
wave_assignments = {}  # test_id -> (runner_id, wave)
wave_runners = defaultdict(lambda: defaultdict(lambda: {'cpu': 0, 'mem': 0, 'count': 0, 'tests': []}))

# Track mutual exclusion within waves
runner_wave_flaky = defaultdict(lambda: defaultdict(set))  # (runner_id, wave) -> set of test_ids
runner_wave_nonflaky = defaultdict(lambda: defaultdict(set))  # (runner_id, wave) -> set of test_ids

for t in sorted_tests:
    tid = t['test_id']
    ew = earliest_wave[tid]

    # Try to find a runner for this test in wave ew or higher
    best_runner = None
    best_wave = ew

    for r_id, r_info in runner_map.items():
        # Check runner capability: category and gpu
        if category[tid] not in r_info['supported_categories']:
            continue
        if gpu_required[tid] and not r_info['has_gpu']:
            continue
        # Check affinity
        if tid in affinity and affinity[tid] != r_id:
            continue
        # Check critical reliability
        if critical[tid] and r_info['reliability_score'] < critical_reliability_threshold:
            continue
        # Check mutual exclusion: none of the tests in its mutual exclusion group can be in this wave
        conflict = False
        for other in mutual_exclusion:
            if tid in other:
                if other[0] in wave_assignments and wave_assignments[other[0]][1] == ew:
                    conflict = True
                    break
                if other[1] in wave_assignments and wave_assignments[other[1]][1] == ew:
                    conflict = True
                    break
        if conflict:
            continue
        # Check flaky isolation
        tf = flaky[tid]
        if tf:
            for tid2 in wave_runners[r_id][ew]['tests']:
                if not flaky[tid2]:
                    conflict = True
                    break
            if conflict:
                continue
        else:
            for tid2 in wave_runners[r_id][ew]['tests']:
                if flaky[tid2]:
                    conflict = True
                    break
            if conflict:
                continue
        # Check resource buffer (10% buffer means actual <= capacity * 1.10)
        cpu_used = wave_runners[r_id][ew]['cpu']
        mem_used = wave_runners[r_id][ew]['mem']
        count_used = wave_runners[r_id][ew]['count']

        if cpu_used + cpu[tid] > runner_capacity[r_id]['cpu'] * 1.10:
            continue
        if mem_used + memory[tid] > runner_capacity[r_id]['memory'] * 1.10:
            continue
        if count_used + 1 > r_info['max_concurrent_tests']:
            continue

        # This runner is valid!
        best_runner = r_id
        best_wave = ew
        break

    if best_runner is None:
        # Try higher waves
        ew = ew + 1
        while True:
            for r_id, r_info in runner_map.items():
                if category[tid] not in r_info['supported_categories']:
                    continue
                if gpu_required[tid] and not r_info['has_gpu']:
                    continue
                if tid in affinity and affinity[tid] != r_id:
                    continue
                if critical[tid] and r_info['reliability_score'] < critical_reliability_threshold:
                    continue
                conflict = False
                for other in mutual_exclusion:
                    if tid in other:
                        if other[0] in wave_assignments and wave_assignments[other[0]][1] == ew:
                            conflict = True
                            break
                        if other[1] in wave_assignments and wave_assignments[other[1]][1] == ew:
                            conflict = True
                            break
                if conflict:
                    continue
                tf = flaky[tid]
                if tf:
                    for tid2 in wave_runners[r_id][ew]['tests']:
                        if not flaky[tid2]:
                            conflict = True
                            break
                    if conflict:
                        continue
                else:
                    for tid2 in wave_runners[r_id][ew]['tests']:
                        if flaky[tid2]:
                            conflict = True
                            break
                    if conflict:
                        continue
                cpu_used = wave_runners[r_id][ew]['cpu']
                mem_used = wave_runners[r_id][ew]['mem']
                count_used = wave_runners[r_id][ew]['count']

                if cpu_used + cpu[tid] > runner_capacity[r_id]['cpu'] * 1.10:
                    continue
                if mem_used + memory[tid] > runner_capacity[r_id]['memory'] * 1.10:
                    continue
                if count_used + 1 > r_info['max_concurrent_tests']:
                    continue

                best_runner = r_id
                best_wave = ew
                break
            if best_runner is not None:
                break
            else:
                ew += 1
                if ew > 100:
                    print(f"FATAL ERROR: Could not find runner for test {tid}")
                    exit(1)

    wave_assignments[tid] = (best_runner, best_wave)

    # Update wave_runners
    r_id, wave = best_runner, best_wave
    wave_runners[r_id][wave]['cpu'] += cpu[tid]
    wave_runners[r_id][wave]['mem'] += memory[tid]
    wave_runners[r_id][wave]['count'] += 1
    wave_runners[r_id][wave]['tests'].append(tid)

    # Update flaky isolation tracking
    if flaky[tid]:
        runner_wave_flaky[r_id][wave].add(tid)
    else:
        runner_wave_nonflaky[r_id][wave].add(tid)

# Verify constraints
print("\n--- Constraint Verification ---")
all_ok = True

# 1. Dependency Ordering
print("1. Dependency Ordering...")
for tid, (r_id, wave) in wave_assignments.items():
    deps = test_map[tid]['dependencies']
    all_satisfied = True
    for dep in deps:
        if dep not in wave_assignments:
            print(f"  FAIL: {tid} depends on {dep} but {dep} not assigned")
            all_ok = False
            continue
        dep_wave = wave_assignments[dep][1]
        if dep_wave >= wave:
            print(f"  FAIL: {tid} depends on {dep} but {dep} is in wave {dep_wave} >= {wave}")
            all_ok = False
            continue
    if not all_ok:
        break
print("  Result: " + ("PASS" if all_ok else "FAIL"))

# 2. Runner Capability
print("2. Runner Capability...")
all_ok = True
for tid, (r_id, wave) in wave_assignments.items():
    t = test_map[tid]
    r = runner_map[r_id]
    if t['category'] not in r['supported_categories']:
        print(f"  FAIL: {tid} category {t['category']} not supported by {r_id}")
        all_ok = False
    if t['gpu_required'] and not r['has_gpu']:
